use clap::Parser;
use crossterm::{
    event::{self, Event, KeyCode, KeyEvent, KeyModifiers},
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
};
use std::fs;
use std::io;
use std::time::Instant;

mod ngrams;
mod ui;
mod keyboard;

use ngrams::Ngrams;
use ui::UI;

#[derive(Parser, Debug)]
#[command(name = "executable")]
#[command(about = "Practice typing n-grams")]
struct Args {
    #[arg(short = 'n', long = "n", default_value = "2", value_parser = parse_ngram_type)]
    n: String,

    #[arg(short = 't', long = "top", default_value = "50")]
    top: usize,

    #[arg(short = 'c', long = "combi", default_value = "2")]
    combi: usize,

    #[arg(short = 'r', long = "rep", default_value = "3")]
    rep: usize,

    #[arg(short = 'w', long = "wpm", default_value = "40")]
    wpm: usize,

    #[arg(short = 'a', long = "acc", default_value = "94")]
    acc: usize,

    #[arg(long = "emu-in", default_value = "")]
    emu_in: String,

    #[arg(long = "emu-out", default_value = "")]
    emu_out: String,

    #[arg(long = "show-ortho")]
    show_ortho: bool,

    #[arg(long = "nokb")]
    nokb: bool,

    #[arg(long = "cat")]
    cat: bool,
}

fn parse_ngram_type(s: &str) -> Result<String, String> {
    match s {
        "2" | "3" | "4" | "w" => Ok(s.to_string()),
        _ => Ok(s.to_string()), // Could be a file path
    }
}

fn main() -> io::Result<()> {
    let args = Args::parse();

    // Validate arguments
    if args.top < 1 || args.top > 200 {
        eprintln!("Invalid argument for top. Use a number between 1 and 200.");
        std::process::exit(1);
    }

    if args.combi < 1 || args.combi > 200 {
        eprintln!("Invalid argument for combi. Use a number between 1 and 200.");
        std::process::exit(1);
    }

    if args.rep < 1 || args.rep > 200 {
        eprintln!("Invalid argument for rep. Use a number between 1 and 200.");
        std::process::exit(1);
    }

    if args.wpm < 1 || args.wpm > 200 {
        eprintln!("Invalid argument for wpm. Use a number between 1 and 200.");
        std::process::exit(1);
    }

    if args.acc > 100 {
        eprintln!("Invalid argument for acc. Use a number between 0 and 100.");
        std::process::exit(1);
    }

    // Check layout emulation
    if (!args.emu_in.is_empty() && args.emu_out.is_empty())
        || (args.emu_in.is_empty() && !args.emu_out.is_empty())
    {
        eprintln!("You need to specify both emu_in and emu_out.");
        std::process::exit(1);
    }

    // Load ngrams based on the type
    let ngrams = match args.n.as_str() {
        "2" => ngrams::load_bigrams(args.top, args.combi, args.rep),
        "3" => ngrams::load_trigrams(args.top, args.combi, args.rep),
        "4" => ngrams::load_tetragrams(args.top, args.combi, args.rep),
        "w" => ngrams::load_words(args.top, args.combi, args.rep),
        _ => {
            // Try to load from file
            match fs::read_to_string(&args.n) {
                Ok(content) => ngrams::load_from_file(&content, args.top, args.combi, args.rep),
                Err(_) => {
                    eprintln!("File not found: {}", args.n);
                    std::process::exit(1);
                }
            }
        }
    };

    // Setup terminal
    enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen)?;

    let result = run_lesson(&args, ngrams);

    execute!(stdout, LeaveAlternateScreen)?;
    disable_raw_mode()?;

    result
}

fn run_lesson(_args: &Args, ngrams: Ngrams) -> io::Result<()> {
    let mut ui = UI::new(ngrams)?;
    let mut input = String::new();
    let mut start_time: Option<Instant> = None;

    loop {
        ui.draw()?;

        if event::poll(std::time::Duration::from_millis(100))? {
            if let Event::Key(key) = event::read()? {
                match key.code {
                    KeyCode::Esc => break,
                    KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => break,
                    KeyCode::Char(c) => {
                        if start_time.is_none() {
                            start_time = Some(Instant::now());
                        }
                        input.push(c);
                        ui.add_input(c);
                    }
                    KeyCode::Backspace => {
                        if !input.is_empty() {
                            input.pop();
                            ui.backspace();
                        }
                    }
                    KeyCode::Enter => {
                        // Check if we're done with this ngram
                        if ui.check_input(&input) {
                            input.clear();
                            if ui.next_ngram() {
                                // Lesson complete
                                break;
                            }
                        }
                    }
                    _ => {}
                }
            }
        }
    }

    Ok(())
}
