cat > src/ui.rs << 'EOF'
use crossterm::{execute, terminal::size};
use std::io::{self, Write};

use crate::ngrams::Ngrams;

pub struct UI {
    ngrams: Ngrams,
    current_input: String,
    correct_count: usize,
    error_count: usize,
}

impl UI {
    pub fn new(ngrams: Ngrams) -> io::Result<Self> {
        let ui = UI {
            ngrams,
            current_input: String::new(),
            correct_count: 0,
            error_count: 0,
        };
        Ok(ui)
    }

    pub fn draw(&self) -> io::Result<()> {
        let stdout = io::stdout();
        let mut handle = stdout.lock();

        // Clear screen
        write!(handle, "\x1B[2J\x1B[H")?;

        let current = self.ngrams.current();
        write!(handle, "Type: {}\r\n", current)?;
        write!(handle, "Input: {}\r\n", self.current_input)?;
        write!(
            handle,
            "Correct: {} | Errors: {}\r\n",
            self.correct_count, self.error_count
        )?;

        handle.flush()?;
        Ok(())
    }

    pub fn add_input(&mut self, c: char) {
        self.current_input.push(c);
    }

    pub fn backspace(&mut self) {
        self.current_input.pop();
    }

    pub fn check_input(&mut self, input: &str) -> bool {
        if input == self.ngrams.current() {
            self.correct_count += 1;
            true
        } else {
            self.error_count += 1;
            false
        }
    }

    pub fn next_ngram(&mut self) -> bool {
        !self.ngrams.advance()
    }
}
