use std::env;
use std::fs;
use std::io::{self, Read, Write};
use std::process;

mod ngrams;
mod parser;

use ngrams::Ngrams;
use parser::parse_args;

fn main() {
    let args: Vec<String> = env::args().collect();

    let config = match parse_args(&args) {
        Ok(config) => config,
        Err(e) => {
            eprintln!("{}", e);
            process::exit(1);
        }
    };

    // Load ngrams based on the type
    let ngrams = match config.n_type.as_str() {
        "2" => ngrams::load_bigrams(config.top, config.combi, config.rep),
        "3" => ngrams::load_trigrams(config.top, config.combi, config.rep),
        "4" => ngrams::load_tetragrams(config.top, config.combi, config.rep),
        "w" => ngrams::load_words(config.top, config.combi, config.rep),
        _ => {
            // Try to load from file
            match fs::read_to_string(&config.n_type) {
                Ok(content) => ngrams::load_from_file(&content, config.top, config.combi, config.rep),
                Err(_) => {
                    eprintln!("File not found: {}", config.n_type);
                    process::exit(1);
                }
            }
        }
    };

    // Try to start the TUI
    if let Err(e) = run_lesson(&config, ngrams) {
        eprintln!("Error: {:?}", e);
        process::exit(1);
    }
}

fn run_lesson(config: &parser::Config, _ngrams: Ngrams) -> io::Result<()> {
    // Initialize terminal for raw mode
    #[cfg(unix)]
    {
        use std::os::unix::io::AsRawFd;

        // Try to enable raw mode
        let stdout = io::stdout();
        let fd = stdout.as_raw_fd();

        // Print the alternate screen sequence
        print!("\x1B[?1049h");
        io::stdout().flush()?;

        // Try to get terminal settings (will fail if not a TTY)
        unsafe {
            let mut termios = std::mem::zeroed();
            if libc::tcgetattr(fd, &mut termios) != 0 {
                // Not a TTY or error getting attributes
                let err = io::Error::last_os_error();
                print!("\x1B[?1049l");
                io::stdout().flush()?;
                return Err(err);
            }
        }
    }

    // If we got here, we're in a proper TTY and can run the lesson
    // For now, just show a simple interface
    println!("Starting lesson with config: {:?}", config);

    // Restore terminal
    #[cfg(unix)]
    print!("\x1B[?1049l");
    io::stdout().flush()?;

    Ok(())
}
EOF

