use std::fmt;

#[derive(Debug)]
pub struct Config {
    pub n_type: String,
    pub top: usize,
    pub combi: usize,
    pub rep: usize,
    pub wpm: usize,
    pub acc: usize,
    pub emu_in: String,
    pub emu_out: String,
    pub show_ortho: bool,
    pub nokb: bool,
    pub cat: bool,
}

impl Default for Config {
    fn default() -> Self {
        Config {
            n_type: "2".to_string(),
            top: 50,
            combi: 2,
            rep: 3,
            wpm: 40,
            acc: 94,
            emu_in: String::new(),
            emu_out: String::new(),
            show_ortho: false,
            nokb: false,
            cat: false,
        }
    }
}

pub fn parse_args(args: &[String]) -> Result<Config, String> {
    let mut config = Config::default();
    let mut i = 1; // Skip program name

    while i < args.len() {
        match args[i].as_str() {
            "-h" | "--help" => {
                print_help();
                std::process::exit(0);
            }
            "-n" | "--n" => {
                i += 1;
                if i >= args.len() {
                    return Err("Option -n requires an argument".to_string());
                }
                config.n_type = args[i].clone();
            }
            "-t" | "--top" => {
                i += 1;
                if i >= args.len() {
                    return Err("Option -t requires an argument".to_string());
                }
                config.top = args[i]
                    .parse::<usize>()
                    .map_err(|_| "Invalid value for -t".to_string())?;
                if config.top < 1 || config.top > 200 {
                    return Err("Invalid argument for top. Use a number between 1 and 200.".to_string());
                }
            }
            "-c" | "--combi" => {
                i += 1;
                if i >= args.len() {
                    return Err("Option -c requires an argument".to_string());
                }
                config.combi = args[i]
                    .parse::<usize>()
                    .map_err(|_| "Invalid value for -c".to_string())?;
                if config.combi < 1 || config.combi > 200 {
                    return Err("Invalid argument for combi. Use a number between 1 and 200.".to_string());
                }
            }
            "-r" | "--rep" => {
                i += 1;
                if i >= args.len() {
                    return Err("Option -r requires an argument".to_string());
                }
                config.rep = args[i]
                    .parse::<usize>()
                    .map_err(|_| "Invalid value for -r".to_string())?;
                if config.rep < 1 || config.rep > 200 {
                    return Err("Invalid argument for rep. Use a number between 1 and 200.".to_string());
                }
            }
            "-w" | "--wpm" => {
                i += 1;
                if i >= args.len() {
                    return Err("Option -w requires an argument".to_string());
