cat > src/ngrams.rs << 'EOF'
pub struct Ngrams {
    pub items: Vec<String>,
    pub current_index: usize,
}

impl Ngrams {
    pub fn new(items: Vec<String>) -> Self {
        Ngrams {
            items,
            current_index: 0,
        }
    }

    pub fn current(&self) -> &str {
        if self.current_index < self.items.len() {
            &self.items[self.current_index]
        } else {
            ""
        }
    }

    pub fn advance(&mut self) -> bool {
        self.current_index += 1;
        self.current_index < self.items.len()
    }

    pub fn is_complete(&self) -> bool {
        self.current_index >= self.items.len()
    }
}

// Simple shuffle implementation without external crates
fn shuffle<T>(vec: &mut Vec<T>) {
    // Simple Linear Congruential Generator for deterministic seeding
    let mut seed: u64 = 12345;

    for i in (1..vec.len()).rev() {
        seed = seed.wrapping_mul(1103515245).wrapping_add(12345);
        let j = (seed as usize) % (i + 1);
        vec.swap(i, j);
    }
}

pub fn load_bigrams(top: usize, combi: usize, rep: usize) -> Ngrams {
    let bigrams = get_top_bigrams(top);
    let selected: Vec<String> = bigrams.into_iter().take(combi).collect();

    let mut all_items = Vec::new();
    for _ in 0..rep {
        all_items.extend(selected.iter().cloned());
    }

    shuffle(&mut all_items);

    Ngrams::new(all_items)
}

pub fn load_trigrams(top: usize, combi: usize, rep: usize) -> Ngrams {
    let trigrams = get_top_trigrams(top);
    let selected: Vec<String> = trigrams.into_iter().take(combi).collect();

    let mut all_items = Vec::new();
    for _ in 0..rep {
        all_items.extend(selected.iter().cloned());
    }

    shuffle(&mut all_items);

    Ngrams::new(all_items)
}

pub fn load_tetragrams(top: usize, combi: usize, rep: usize) -> Ngrams {
    let tetragrams = get_top_tetragrams(top);
    let selected: Vec<String> = tetragrams.into_iter().take(combi).collect();

    let mut all_items = Vec::new();
    for _ in 0..rep {
        all_items.extend(selected.iter().cloned());
    }

    shuffle(&mut all_items);

    Ngrams::new(all_items)
}

pub fn load_words(top: usize, combi: usize, rep: usize) -> Ngrams {
    let words = get_top_words(top);
    let selected: Vec<String> = words.into_iter().take(combi).collect();

    let mut all_items = Vec::new();
    for _ in 0..rep {
        all_items.extend(selected.iter().cloned());
    }

    shuffle(&mut all_items);

    Ngrams::new(all_items)
}

pub fn load_from_file(content: &str, _top: usize, combi: usize, rep: usize) -> Ngrams {
    let items: Vec<String> = content
